function make(name,kind,prompt){const d=now();return{id:id(),name:word(name)||"Untitled Project",kind,description:word(prompt)||"A new web project",created:d,updated:d,files:template(kind,name,prompt),history:[]};}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state.projects));document.querySelectorAll("[data-saved]").forEach(x=>x.textContent="Saved locally")}catch(e){notify("Storage full. Export your project ZIP.")}}
function load(){try{const p=JSON.parse(localStorage.getItem(KEY)||"null");if(Array.isArray(p)){state.projects=p;return}}catch(e){}state.projects=[make("Northstar Insights","dashboard","Analytics dashboard to monitor revenue and customers"),make("Studio Portfolio","portfolio","A creative personal portfolio website")];persist();}
function current(){return state.projects.find(p=>p.id===state.active)}
function shell(content,section){const navigation=[["dashboard","Overview"],["projects","My projects"],["cloud","Cloud IDE"],["design","Design canvas"],["templates","Templates"],["help","Help & guide"]].map(([key,label])=>'<button data-nav="'+key+'" class="'+(section===key?"active":"")+'"><span class="glyph">'+icons[key]+'</span><span>'+label+'</span></button>').join("");return '<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">◆</div><div><strong>PrismForge</strong><small>CLOUD STUDIO</small></div></div><div class="navhead">Workspace</div><div class="nav">'+navigation+'</div><div class="sidebottom"><div class="sidecall"><strong>Launch your next idea</strong><p>Start from a prompt, then refine every line of code.</p><button data-action="new">＋ New workspace</button></div><div class="sidefoot"><div class="avatar">PF</div><div><b>Local workspace</b><small>Stored on this browser</small></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Workspace <span>›</span> <strong>'+safe(section==="dashboard"?"Overview":section==="editor"?"Code Studio":section==="projects"?"My projects":section==="cloud"?"Linux workspace":section==="design"?"Design canvas":section==="templates"?"Starter templates":"Help & guide")+'</strong></div><div class="topact"><div class="topstatus"><span class="dot"></span>Browser workspace</div><button data-action="cloudaccount" class="button small">☁ Account</button><button data-action="settings" class="button subtle small">⚙ Settings</button><button data-action="new" class="button primary small">＋ New project</button></div></header>'+content+'</main></div>';}
function card(p){let k=kinds.find(t=>t.id===p.kind)||kinds[0];return '<article class="project"><div class="projecticon">'+k.icon+'</div><strong>'+safe(p.name)+'</strong><p>'+safe(p.description)+'</p><div class="projectbottom"><span class="tag">'+safe(k.name)+'</span><span>'+fmt(p.updated)+'</span><button class="iconbtn" data-open="'+safe(p.id)+'" aria-label="Open '+safe(p.name)+'">↗</button></div><div style="display:flex;gap:6px;margin-top:12px"><button class="button subtle small" data-open="'+safe(p.id)+'">Open editor</button><button class="button subtle small" data-duplicate="'+safe(p.id)+'">Duplicate</button><button class="button subtle small danger" data-delete="'+safe(p.id)+'">Delete</button></div></article>';}
function projectList(filter){const ps=state.projects.filter(p=>(p.name+" "+p.description+" "+p.kind).toLowerCase().includes((filter||"").toLowerCase()));return ps.length?ps.map(card).join(""):'<div class="empty">No matching projects. Start with a prompt or choose a template.</div>';}
function tmplCards(){return kinds.map(k=>'<button class="template" data-template="'+k.id+'"><span>'+k.icon+'</span><b>'+k.name+'</b><small>'+k.desc+'</small></button>').join("");}
function dashboard(){let section=state.view;let main="";if(section==="dashboard"){main='<div class="wrap"><div class="eyebrow">YOUR CREATIVE OPERATING SYSTEM</div><h1 class="heading">Build what is next.</h1><p class="lead">From first idea to working website. One focused workspace for your code.</p><section class="hero"><div class="herocap">✦ '+(hasAI()?"AI coding connected":"Prompt-to-project builder")+'</div><h2>Describe your idea.<br>Start building immediately.</h2><p>Generate a working web starter, edit every file and see changes live.</p><textarea id="mainPrompt" class="promptfield" placeholder="Example: Build an analytics dashboard to track sales, customers and monthly growth...">'+safe(state.draft)+'</textarea><div class="heroactions"><button data-action="generate" class="button primary">✦ '+(hasAI()?"Generate with AI ↗":"Generate project ↗")+'</button><span class="micro">'+(hasAI()?"Cloud AI agent selected":"Free templates. Sign in for AI code generation.")+'</span></div></section><div class="statgrid"><div class="stat"><div><small>Your projects</small><strong>'+state.projects.length+'</strong></div><i>▦</i></div><div class="stat"><div><small>Browser file types</small><strong>7+</strong></div><i>⌘</i></div><div class="stat"><div><small>Linux IDE</small><strong>VS Code</strong></div><i>◉</i></div></div><section class="cloudfeature"><div><div class="eyebrow">FULL LINUX DEVELOPMENT ENVIRONMENT</div><h2>Use a real terminal, Git and packages.</h2><p>Open a password-protected VS Code workspace with Node.js, Python, Git, package installation and extensions. Sandboxed compute is session-based and expires automatically.</p><div class="cloudactions"><button class="button primary" data-action="opencloud">Open Linux IDE ↗</button><button class="button" data-nav="cloud">Workspace details</button></div></div><div class="cloudglyph">⌘</div></section><div class="rowtitle"><div><h3>Recent projects</h3><p>Resume where you left off.</p></div><div style="display:flex;gap:8px"><button class="button small" data-action="github">⌘ Import GitHub</button><button class="button small" data-action="import">↑ Import ZIP</button><button class="button small" data-nav="projects">View all projects ↗</button></div></div><div class="cards">'+state.projects.slice().sort((a,b)=>b.updated.localeCompare(a.updated)).slice(0,3).map(card).join("")+'</div><div class="rowtitle"><div><h3>Start from a template</h3><p>Working foundations for your next website.</p></div></div><div class="templates">'+tmplCards()+'</div><p class="footerhint">PrismForge Cloud · Privacy-first local workspace · V1.0</p></div>';}
if(section==="projects"){main='<div class="wrap"><div class="eyebrow">YOUR WORKSPACES</div><h1 class="heading">My projects</h1><p class="lead">Browse, edit, duplicate and export your work.</p><div class="rowtitle"><h3>'+state.projects.length+' projects</h3><div class="filterbar"><input class="search" id="searchProjects" placeholder="Search projects..." value="'+safe(state.query)+'"><button data-action="github" class="button">⌘ GitHub</button><button data-action="import" class="button">↑ Import ZIP</button><button data-action="cloudsync" class="button">☁ Sync cloud</button><button data-action="new" class="button primary">＋ Create</button></div></div><div class="cards" id="projectResults">'+projectList(state.query)+'</div></div>';}
if(section==="templates"){main='<div class="wrap"><div class="eyebrow">START WITH MOMENTUM</div><h1 class="heading">Starter library</h1><p class="lead">Each template includes editable HTML, CSS, JavaScript and a live preview.</p><div class="rowtitle"><h3>Browse templates</h3></div><div class="templates">'+tmplCards()+'</div><div class="notice" style="margin-top:32px">Project generation works offline from local starter templates. An AI model is not connected in this release.</div></div>';}
if(section==="design"){state.view="design";renderDesignCanvas();return}
if(section==="cloud"){main='<div class="wrap"><div class="eyebrow">LINUX WORKSPACE / PRIVATE ACCESS</div><h1 class="heading">Cloud IDE.</h1><p class="lead">An isolated Linux environment running the open-source browser version of VS Code.</p><section class="cloudfeature" style="margin-top:28px"><div><div class="eyebrow">RUN REAL CODE</div><h2>Go beyond HTML previews.</h2><p>Use the integrated shell, clone repositories, install dependencies, run npm scripts, debug applications, and manage Git branches inside a Linux container.</p><div class="cloudactions"><button class="button primary" data-action="opencloud">Launch password-protected editor ↗</button></div></div><div class="cloudglyph">⌘</div></section><div class="statgrid"><div class="stat"><div><small>Runtime</small><strong>Linux</strong></div><i>▤</i></div><div class="stat"><div><small>Editor</small><strong>VS Code</strong></div><i>⌘</i></div><div class="stat"><div><small>Isolation</small><strong>Sandbox</strong></div><i>◉</i></div></div><section class="panel"><h3>What works inside the Linux editor</h3><p>Real Linux terminal, filesystem, Node.js, Python, Git, debugging, extensions and package managers. You enter the password supplied privately by the workspace owner.</p></section><section class="panel"><h3>Session lifecycle</h3><p>This workspace runs inside an ephemeral compute session. Its URL stops serving when the session ends. Vercel snapshots preserve files for a limited period, subject to platform limits. An operator must resume the named sandbox and relaunch the editor if necessary.</p></section><section class="panel"><h3>Browser projects versus Linux projects</h3><p>Projects made in the browser editor remain in your local browser storage. Export a ZIP and upload its extracted files through VS Code Explorer to work on the project in Linux. These two workspaces are not automatically synchronized yet.</p></section><div class="notice" style="margin-top:22px">Current Linux workspace is a single-owner development environment. This is not yet a hosted multi-tenant service. The production-grade account system, isolated per-user runtimes, collaboration, AI agents and deployment orchestration are still separate development milestones.</div></div>';}
if(section==="help"){main='<div class="wrap" style="max-width:980px"><div class="eyebrow">YOUR WORKSPACE MANUAL</div><h1 class="heading">Build with confidence.</h1><p class="lead">PrismForge is focused on browser-based HTML, CSS and JavaScript projects.</p><section class="panel"><h3>1. Create a project</h3><p>Describe your idea using the prompt builder or choose a starter template. The local builder matches your request to one of seven starter types.</p></section><section class="panel"><h3>2. Edit and preview</h3><p>Open any project, select a file and edit its contents. The preview updates automatically inside a sandboxed iframe. Switch between desktop and mobile views.</p></section><section class="panel"><h3>3. Save, restore and export</h3><p>Your changes auto-save in this browser. Save a named snapshot before major changes. Export a project as a standard ZIP archive, then deploy the extracted files with a hosting provider.</p></section><section class="panel"><h3>Important limits</h3><p>This release stores work in browser localStorage. There is no account sync, backend runtime, remote terminal, package manager or production-grade AI code generation. Export backups before clearing browser data.</p></section><button class="button primary" data-action="new">＋ Start a project</button></div>';}
app.innerHTML=shell(main,section);if(section==="projects")setTimeout(()=>document.getElementById("searchProjects")?.focus(),50);}


function canvasVariantCSS(type) {
 if(type==="dark")return "body,.site{background:#101522!important;color:#e8ecfa!important} .site nav,.site .panel,.site article,.site section,.site .metric,.site form,.site .taskrow{background:#1b2440!important;color:#e8ecfa!important;border-color:#38435f!important} .site p,.site small{color:#b3bfda!important}.site button,.site .cta{border-radius:6px!important}";
 if(type==="vivid")return "body,.site{background:#fff9f3!important;color:#292138!important}.site h1,.site h2{letter-spacing:-.07em!important}.site .cta,.site button{background:#ed5d70!important;color:#fff!important;border-radius:50px!important}.site article,.site .panel,.site .metric{border-radius:24px!important;box-shadow:0 12px 40px #ed5d701a!important}.site em{color:#ed5d70!important}";
 return "body,.site{background:#f8fafc!important;color:#172234!important}.site h1{font-weight:600!important;letter-spacing:-.04em!important}.site .cta,.site button{border-radius:2px!important}.site article,.site .panel,.site .metric{border-radius:3px!important;box-shadow:none!important}.site nav{border-bottom:1px solid #e2e8f0!important}";
}
function renderDesignCanvas(){
 const p=current();
 if(!p){state.view="projects";dashboard();notify("Open a project and select Design Canvas.");return}
 const options=[["minimal","Minimal studio","Editorial hierarchy and flat controls"],["dark","Midnight","Dark surfaces with contrast"],["vivid","Vivid","Warm editorial palette and rounded actions"]];
 const cards=options.map(([id,name,description])=>'<article class="designvariant"><div class="designpreview"><iframe data-designframe="'+id+'" sandbox="" title="'+safe(name)+' design preview"></iframe></div><div class="designmeta"><strong>'+name+'</strong><p>'+description+'</p><button class="button small primary" data-applydesign="'+id+'">Apply to project ↗</button></div></article>').join("");
 app.innerHTML=shell('<div class="wrap designwrap"><div class="eyebrow">EXPLORE / COMPARE / APPLY</div><h1 class="heading">Design canvas.</h1><p class="lead">Preview three visual directions using the live source of '+safe(p.name)+'. Apply one and continue editing your code.</p><div class="rowtitle"><h3>Visual directions</h3><button class="button" data-designback="true">← Back to editor</button></div><div class="designgrid">'+cards+'</div><div class="notice" style="margin-top:24px">Applying a direction saves a snapshot and updates style.css. You retain full control of your source. This is a style variation system, not an AI-generated design canvas.</div></div>',"design");
 const original=sourceDoc(p);
 document.querySelectorAll("[data-designframe]").forEach(frame=>{
  const style='<style id="prismforge-variant">'+canvasVariantCSS(frame.dataset.designframe)+'</style>';
  frame.srcdoc=original.replace(/<\/head>/i,style+'</head>');
 });
}
function applyDesign(id){
 if(!["minimal","dark","vivid"].includes(id))return;
 const p=current();if(!p)return;
 snapshot();
 const marker="/* PRISMFORGE DESIGN VARIANT */";
 const currentCss=p.files["style.css"]||"";
 const existing=currentCss.indexOf(marker);
 p.files["style.css"]=(existing>=0?currentCss.slice(0,existing):currentCss)+"\n"+marker+"\n"+canvasVariantCSS(id)+"\n";
 p.updated=now();persist();state.view="editor";state.file="style.css";editor();notify("Design applied. Previous CSS saved as a snapshot.");
}

function enableRichEditor(){
 if(!window.CodeMirror)return;
 const ta=document.getElementById("codeEditor");
 if(!ta)return;
 try{
  const lang=state.file.endsWith(".html")?"htmlmixed":state.file.endsWith(".css")?"css":state.file.endsWith(".js")?"javascript":"text/plain";
  const cm=window.CodeMirror.fromTextArea(ta,{mode:lang,lineNumbers:true,lineWrapping:false,tabSize:2,indentUnit:2,theme:"default",viewportMargin:10});
  window._prismCm=cm;
  const linenums=document.getElementById("linenums");if(linenums)linenums.style.display="none";
  cm.setSize("100%","100%");
  cm.on("change",()=>{ta.value=cm.getValue();syncEditor()});
  cm.on("cursorActivity",()=>{const pos=cm.getCursor(),spot=document.getElementById("cursorpos");if(spot)spot.textContent="Ln "+(pos.line+1)+" · Col "+(pos.ch+1)});
  cm.refresh();
 }catch(err){console.warn("Code editor enhancement unavailable",err);}
}
function unzipOwn(buffer){
 const bytes=new Uint8Array(buffer),view=new DataView(buffer),dec=new TextDecoder();let pos=0,files={};
 while(pos+30<=bytes.length){
  if(view.getUint32(pos,true)!==0x04034b50)break;
  const flags=view.getUint16(pos+6,true),method=view.getUint16(pos+8,true),size=view.getUint32(pos+18,true),nameLen=view.getUint16(pos+26,true),extraLen=view.getUint16(pos+28,true);
  if(flags&8||method!==0)throw Error("Import supports uncompressed PrismForge ZIP files.");
  const begin=pos+30+nameLen+extraLen,end=begin+size;
  if(end>bytes.length)throw Error("Invalid ZIP contents.");
  const name=dec.decode(bytes.slice(pos+30,pos+30+nameLen));
  if(/^[\w.-]+\.(html|css|js|json|md|txt)$/i.test(name)&&!name.includes(".."))files[name]=dec.decode(bytes.slice(begin,end));
  pos=end;
 }
 if(!files["index.html"])throw Error("ZIP must contain index.html.");
 return files;
}
async function importOwnProject(){
 const input=document.getElementById("importZip"),file=input?.files?.[0];if(!file){notify("Select a ZIP file.");return;}
 try{const files=unzipOwn(await file.arrayBuffer()),name=file.name.replace(/\.zip$/i,"")||"Imported Project";const p=make(name,"landing","Imported web project");p.files=files;state.projects.unshift(p);persist();queueCloudSave(p);closeModal();openProject(p.id);notify("Project imported successfully.");}catch(e){notify(e.message||"Import failed.");}
}


async function importPublicGithub(){
 const value=(document.getElementById("githubUrl")?.value||"").trim();
 let u;try{u=new URL(value)}catch(e){notify("Enter a valid GitHub repository URL.");return}
 if(u.hostname!=="github.com"&&u.hostname!=="www.github.com"){notify("Only public github.com URLs are supported.");return}
 const [owner,repo]=u.pathname.replace(/\/$/,"").split("/").filter(Boolean);
 if(!owner||!repo||!/^[\w.-]+$/.test(owner)||!/^[\w.-]+$/.test(repo)){notify("Use https://github.com/owner/repository");return}
 const btn=document.querySelector('[data-action="importgithub"]');if(btn){btn.disabled=true;btn.textContent="Importing..."}
 try{
  const h={Accept:"application/vnd.github+json"};
  const base="https://api.github.com/repos/"+encodeURIComponent(owner)+"/"+encodeURIComponent(repo);
  const detail=await fetch(base,{headers:h});if(!detail.ok)throw Error("Cannot access repository. Check if public.");
  const data=await detail.json();
  const treeResponse=await fetch(base+"/git/trees/"+encodeURIComponent(data.default_branch)+"?recursive=1",{headers:h});
  if(!treeResponse.ok)throw Error("Cannot read repository tree.");
  const tree=await treeResponse.json();if(tree.truncated)throw Error("Repository is too large for a browser import.");
  const allowed=/\.(html|css|js|jsx|ts|tsx|json|md|txt|py|yml|yaml|toml|sh|sql|vue|svelte|go|rs|java|rb|php)$/i;
  const entries=(tree.tree||[]).filter(x=>x.type==="blob"&&allowed.test(x.path)&&x.size>=0&&x.size<=80000&& !x.path.split("/").includes("node_modules")).slice(0,50);
  if(!entries.length)throw Error("Repository has no supported text files.");
  let total=0;const files={};
  for(let at=0;at<entries.length;at+=5){
   const batch=entries.slice(at,at+5);
   const results=await Promise.all(batch.map(async x=>{
    const link="https://raw.githubusercontent.com/"+encodeURIComponent(owner)+"/"+encodeURIComponent(repo)+"/"+encodeURIComponent(data.default_branch)+"/"+x.path.split("/").map(encodeURIComponent).join("/");
    try{const res=await fetch(link);if(!res.ok)return null;const text=await res.text();return[x.path,text]}catch(e){return null}
   }));
   for(let p of results)if(p){const bytes=new TextEncoder().encode(p[1]).length;if(total+bytes>1500000)break;files[p[0]]=p[1];total+=bytes}
  }
  if(!Object.keys(files).length)throw Error("Unable to retrieve repository files.");
  const p=make(repo,"landing","Imported public GitHub repository: "+owner+"/"+repo);p.files=files;
  if(!p.files["index.html"])p.files["index.html"]='<!doctype html><html lang="en"><head><meta charset="utf-8"><title>GitHub import</title></head><body style="font:16px system-ui;padding:40px"><h1>'+safe(repo)+'</h1><p>Repository imported. Open the files in the editor. For framework builds and package installation, use the Linux IDE.</p></body></html>';
  state.projects.unshift(p);persist();closeModal();openProject(p.id);notify("Imported "+Object.keys(files).length+" GitHub files.");
 }catch(e){notify(e.message||"GitHub import failed.");if(btn){btn.disabled=false;btn.textContent="Import repository ↗"}}
}

function editor(){if(window._prismCm){window._prismCm.toTextArea();window._prismCm=null;}let p=current();if(!p){state.view="projects";dashboard();return;}if(!p.files[state.file])state.file=Object.keys(p.files)[0];const k=kinds.find(x=>x.id===p.kind)||kinds[0];const list=Object.keys(p.files).map(f=>'<button class="fileitem '+(f===state.file?"active":"")+'" data-file="'+safe(f)+'"><span class="fileicon '+(f.endsWith(".css")?"css":f.endsWith(".js")?"js":"")+'">'+(f.endsWith(".html")?"◇":f.endsWith(".css")?"#":"JS")+'</span>'+safe(f)+'</button>').join("");const main='<div class="editorpage"><div class="editorhead"><div class="projectinfo"><div class="projecticon">'+k.icon+'</div><div><strong>'+safe(p.name)+'</strong><small>'+safe(k.name)+' · Editing workspace</small></div></div><div class="editoractions"><button class="button small" data-nav="design">◉ Design canvas</button><button class="button small" data-action="linuxtest">✓ Linux test</button><button class="button small" data-action="linuxrun">▶ Linux run</button><button class="button small" data-action="cloudsave">☁ Save cloud</button><button class="button small" data-action="cloudinvite">♧ Share</button><button class="button small" data-action="snapshot">◷ Snapshot</button><button class="button small" data-action="history">↶ History</button><button class="button small" data-action="replace">✧ Prompt / AI</button><button class="button small" data-action="export">↓ Export ZIP</button><button class="button primary small" data-action="publish">↗ Deploy</button></div></div><div class="editorlayout"><aside class="filepane"><div class="paneheading">Explorer <button class="iconbtn" title="Add file" data-action="addfile">＋</button></div>'+list+'<p class="filetip">Files auto-save in your browser.<br><br>Preview supports index.html, style.css and script.js.<br><br>Ctrl / ⌘ + S: snapshot</p></aside><section class="codepane"><div class="paneheader"><span>⌘ &nbsp; '+safe(state.file)+'</span><span class="panebadge">EDITABLE SOURCE</span></div><div class="editorbox"><div class="lines" id="linenums">1</div><textarea class="codeinput" id="codeEditor" spellcheck="false" autocomplete="off" autocorrect="off" autocapitalize="off" aria-label="Source code editor"></textarea></div><div class="codestatus"><span data-saved>Saved locally</span><span id="cursorpos">Ln 1 · Col 1</span></div></section><section class="previewpane"><div class="previewtoolbar"><small>● &nbsp; Live preview</small><div class="devicetabs"><button class="'+(state.device==="desktop"?"active":"")+'" data-device="desktop">▣ Desktop</button><button class="'+(state.device==="mobile"?"active":"")+'" data-device="mobile">▯ Mobile</button><button title="Open preview in new tab" data-action="popout">↗</button><button title="Refresh preview" data-action="refresh">↻</button></div></div><div id="previewcontainer" class="previewcontainer '+(state.device==="mobile"?"mobile":"")+'"><iframe id="liveFrame" class="previewframe" sandbox="allow-scripts allow-forms allow-modals" referrerpolicy="no-referrer" title="Live project preview"></iframe></div><div class="console"><div class="consolehead"><span>⌘ &nbsp; Preview console</span><button data-action="clearconsole" class="button subtle small">Clear</button></div><div id="consoleentries"></div></div></section></div></div>';app.innerHTML=shell(main,"editor");const ed=document.getElementById("codeEditor");ed.value=p.files[state.file]||"";updateLines();ed.addEventListener("scroll",()=>document.getElementById("linenums").scrollTop=ed.scrollTop);enableRichEditor();preview();drawLogs();}
function sourceDoc(p){let html=p.files["index.html"]||"<!doctype html><html><body><h1>Start building!</h1></body></html>";let style=p.files["style.css"]||"";let script=p.files["script.js"]||"";html=html.replace(/<link\b[^>]*href\s*=\s*["']style\.css["'][^>]*>/gi,"").replace(/<script\b[^>]*src\s*=\s*["']script\.js["'][^>]*><\/script>/gi,"");const styleTag="<style>"+style.replace(/<\/style/gi,"<\\/style")+"</style>";const bridge='(function(){try{["log","warn","error"].forEach(function(m){var orig=console[m];console[m]=function(){try{parent.postMessage({source:"prismforge-preview",type:m,args:Array.from(arguments).map(String)},"*")}catch(e){}orig.apply(console,arguments)}});window.addEventListener("error",function(e){parent.postMessage({source:"prismforge-preview",type:"error",args:[e.message]},"*")})}catch(e){}})();';const scriptTag="<script>"+bridge+"\n"+script.replace(/<\/script/gi,"<\\/script")+"<\/script>";if(/<\/head>/i.test(html))html=html.replace(/<\/head>/i,styleTag+"</head>");else html=styleTag+html;if(/<\/body>/i.test(html))html=html.replace(/<\/body>/i,scriptTag+"</body>");else html+=scriptTag;return html;}
function preview(){const frame=document.getElementById("liveFrame");const p=current();if(!frame||!p)return;try{frame.srcdoc=sourceDoc(p)}catch(e){notify("Preview error: "+e.message)}}
function drawLogs(){const el=document.getElementById("consoleentries");if(el)el.innerHTML=state.logs.slice(-18).map(l=>'<div class="log '+safe(l.type)+'">'+safe(l.text)+'</div>').join("")||'<div class="log">Preview console ready.</div>';}
window.addEventListener("message",e=>{const frame=document.getElementById("liveFrame");if(!frame||e.source!==frame.contentWindow||!e.data||e.data.source!=="prismforge-preview")return;state.logs.push({type:e.data.type,text:(e.data.args||[]).join(" ")});if(state.logs.length>150)state.logs.shift();drawLogs()});
function updateLines(){const ed=document.getElementById("codeEditor");if(!ed)return;const lines=ed.value.split("\n");document.getElementById("linenums").textContent=lines.map((_,i)=>i+1).join("\n");updateCursor();}
function updateCursor(){const ed=document.getElementById("codeEditor");const spot=document.getElementById("cursorpos");if(!ed||!spot)return;const before=ed.value.slice(0,ed.selectionStart),parts=before.split("\n");spot.textContent="Ln "+parts.length+" · Col "+(parts[parts.length-1].length+1);}
function snapshot(){const p=current();if(!p)return;p.history=p.history||[];p.history.unshift({id:id(),at:now(),files:JSON.parse(JSON.stringify(p.files))});p.history=p.history.slice(0,20);p.updated=now();persist();notify("Snapshot saved.");}
function syncEditor(){const ed=document.getElementById("codeEditor"),p=current();if(!p||!ed)return;p.files[state.file]=ed.value;p.updated=now();document.querySelectorAll("[data-saved]").forEach(x=>x.textContent="Saving...");clearTimeout(saveTimer);saveTimer=setTimeout(()=>{persist();preview();queueCloudSave(p)},550);}
function openProject(projectId){if(!state.projects.some(x=>x.id===projectId))return;state.active=projectId;state.file="index.html";state.view="editor";state.logs=[];editor();}
function create(name,kind,prompt){let p=make(name,kind,prompt);state.projects.unshift(p);persist();closeModal();openProject(p.id);notify("Project created. Files are ready to edit.");}
function modalHtml(title,body,footer){return '<div class="overlay" id="overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="'+safe(title)+'"><h2>'+title+'</h2>'+body+'<div class="modalbottom">'+footer+'</div></section></div>';}
function showModal(type,info){state.modal={type,info};let body="",buttons='<button class="button" data-action="closemodal">Close</button>';if(type==="new"){body='<p>Choose a working starter and give your project a name.</p><label for="newName">Project name</label><input id="newName" maxlength="70" placeholder="My new project" value="'+safe(info?.name||"")+'"><label for="newKind">Starter type</label><select id="newKind">'+kinds.map(k=>'<option value="'+k.id+'" '+(k.id===(info?.kind||"landing")?"selected":"")+'>'+k.name+'</option>').join("")+'</select><label for="newDesc">What are you building?</label><textarea id="newDesc" placeholder="Describe the project...">'+safe(info?.prompt||"")+'</textarea><p class="hint">Generates working editable starter files, without a paid model.</p>';buttons='<button class="button" data-action="closemodal">Cancel</button><button class="button primary" data-action="create">Create workspace ↗</button>';}

if(type==="account"){
 body=cloudUser?'<p>Signed in as '+safe(cloudUser.email)+'. Your account has private cloud project storage.</p><div class="notice">Save cloud uploads the active project. Sync cloud downloads projects stored on your account.</div>':'<p>Sign in or create a PrismForge account to store projects across devices.</p><label>Email</label><input id="cloudEmail" type="email" autocomplete="email" placeholder="you@example.com"><label>Password, minimum 12 characters</label><input id="cloudPassword" type="password" autocomplete="current-password"><p class="hint">Email verification and recovery are not included yet. Store your password securely.</p>';
 buttons=cloudUser?'<button class="button" data-action="closemodal">Close</button><button class="button" data-action="cloudsync">Sync cloud</button><button class="button danger" data-action="cloudlogout">Sign out</button>':'<button class="button" data-action="closemodal">Cancel</button><button class="button" data-action="cloudregister">Create account</button><button class="button primary" data-action="cloudlogin">Sign in</button>';
}
if(type==="cloudinvite"){
 body='<p>Share this project with a registered PrismForge account.</p><label>Account email</label><input id="inviteEmail" type="email" placeholder="colleague@example.com"><label>Permission</label><select id="inviteRole"><option value="viewer">Viewer</option><option value="editor">Editor</option></select>';
 buttons='<button class="button" data-action="closemodal">Cancel</button><button class="button primary" data-action="cloudinvitesubmit">Grant access</button>';
}
if(type==="history"){const p=current();body='<p>Restore an earlier manual snapshot. The current state will be saved before restoration.</p>'+((p.history||[]).length?p.history.map((x,i)=>'<div class="historyentry"><span>◷ &nbsp; Snapshot '+(i+1)+'<br><small>'+new Date(x.at).toLocaleString()+'</small></span><button class="button small" data-restore="'+x.id+'">Restore ↶</button></div>').join(""):'<div class="notice">No snapshots yet. Select Snapshot in the editor toolbar.</div>');}
if(type==="publish"){body='<p>Your project is ready to export as a static website.</p><ol class="steps"><li>Download your project ZIP.</li><li>Extract the files and upload to GitHub or a hosting provider.</li><li>Import the project to Vercel or another static hosting service.</li></ol><div class="notice">PrismForge itself is hosted online. Individual projects require an external hosting connection for one-click publishing.</div>';buttons='<button class="button" data-action="closemodal">Close</button><button class="button" data-action="export">↓ Download ZIP</button><button class="button primary" data-action="openvercel">Open Vercel ↗</button>';}
if(type==="github"){body='<p>Import source files from a public GitHub repository. Login and private repositories are not supported in this release.</p><label for="githubUrl">Public GitHub URL</label><input id="githubUrl" type="url" placeholder="https://github.com/owner/repository"><p class="hint">Limits: first 50 supported text files, 1.5 MB total. Modern framework projects require the Linux IDE to build.</p>';buttons='<button class="button" data-action="closemodal">Cancel</button><button class="button primary" data-action="importgithub">Import repository ↗</button>';}
if(type==="import"){body='<p>Restore a project ZIP previously exported by PrismForge Cloud. Your existing projects remain untouched.</p><label for="importZip">Choose ZIP file</label><input id="importZip" type="file" accept=".zip"><p class="hint">Currently supports uncompressed PrismForge ZIP archives.</p>';buttons='<button class="button" data-action="closemodal">Cancel</button><button class="button primary" data-action="processimport">Import project ↗</button>';}
if(type==="settings"){body='<p>PrismForge uses Vercel AI Gateway for authenticated code generation. Your model requests are processed on the server, not with browser-stored keys.</p><div class="notice"><b>Cloud account:</b> '+(cloudUser?"Connected":"Sign in required")+'<br><b>AI model:</b> NVIDIA Nemotron 3.5 Lightning (free listing)<br><b>Project storage:</b> Private Vercel Blob<br><b>Linux terminal:</b> Cloud IDE sandbox</div><p class="hint">Gateway availability is subject to account credits, model limits, and provider access. The backend reports failures rather than generating a fake success.</p>';buttons='<button class="button" data-action="closemodal">Close</button><button class="button primary" data-action="cloudaccount">Manage account</button>';}

if(type==="replace"){body='<p>Describe an idea to generate new starter files inside this project. This replaces existing project code. Export or save a snapshot first.</p><label for="replacePrompt">New concept</label><textarea id="replacePrompt" placeholder="E.g., Build a responsive online store with a shopping bag"></textarea>';buttons='<button class="button" data-action="closemodal">Cancel</button><button class="button primary" data-action="applyprompt">Replace starter ↗</button>';}
document.body.insertAdjacentHTML("beforeend",modalHtml(titleFor(type),body,buttons));}
function titleFor(t){return({new:"Create new project",account:"PrismForge Cloud account",cloudinvite:"Share project",history:"Project snapshots",publish:"Export & deploy",settings:"Workspace settings",github:"Import from GitHub",import:"Import ZIP project",replace:"Generate new starter"})[t]||t;}
function closeModal(){document.getElementById("overlay")?.remove();state.modal=null;}
function crcTable(){const table=[];for(let n=0;n<256;n++){let c=n;for(let j=0;j<8;j++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;table[n]=c>>>0;}return table;}
const CRC=crcTable();function crc32(a){let c=0xffffffff;for(let b of a)c=(c>>>8)^CRC[(c^b)&255];return(c^0xffffffff)>>>0;}
function zipFiles(files){const encoder=new TextEncoder(),parts=[],central=[];let offset=0;const u16=(v,i,n)=>new DataView(v.buffer,v.byteOffset,v.byteLength).setUint16(i,n,true);const u32=(v,i,n)=>new DataView(v.buffer,v.byteOffset,v.byteLength).setUint32(i,n>>>0,true);for(let [name,content]of Object.entries(files)){const nb=encoder.encode(name),data=encoder.encode(content),crc=crc32(data),a=new Uint8Array(30+nb.length),b=new Uint8Array(46+nb.length);u32(a,0,0x04034b50);u16(a,4,20);u32(a,14,crc);u32(a,18,data.length);u32(a,22,data.length);u16(a,26,nb.length);a.set(nb,30);parts.push(a,data);u32(b,0,0x02014b50);u16(b,4,20);u16(b,6,20);u32(b,16,crc);u32(b,20,data.length);u32(b,24,data.length);u16(b,28,nb.length);u32(b,42,offset);b.set(nb,46);central.push(b);offset+=a.length+data.length;}const cdSize=central.reduce((s,b)=>s+b.length,0);const end=new Uint8Array(22);u32(end,0,0x06054b50);u16(end,8,central.length);u16(end,10,central.length);u32(end,12,cdSize);u32(end,16,offset);return new Blob([...parts,...central,end],{type:"application/zip"});}
function download(blob,name){const a=document.createElement("a"),u=URL.createObjectURL(blob);a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),4000);}
function exportProject(){let p=current();if(!p){notify("Open a project first.");return;}const files={...p.files,"README.md":"# "+p.name+"\n\nGenerated in PrismForge Cloud.\n\n"+p.description+"\n\nOpen index.html to view your project in a browser. Edit the HTML, CSS and JavaScript freely.\n"};download(zipFiles(files),slug(p.name)+".zip");notify("ZIP export started.");}
function onAction(a,el){if(a==="linuxtest"){linuxExecute("test");return}if(a==="linuxrun"){linuxExecute("execute");return}if(a==="cloudaccount"){showModal("account");return}if(a==="cloudlogin"){cloudLogin("login");return}if(a==="cloudregister"){cloudLogin("register");return}if(a==="cloudlogout"){cloudLogout();return}if(a==="cloudsync"){closeModal();cloudSync();return}if(a==="cloudsave"){cloudSave(current());return}if(a==="cloudinvite"){showModal(cloudUser?"cloudinvite":"account");return}if(a==="cloudinvitesubmit"){cloudInvite();return}if(a==="clearaikey"){sessionStorage.removeItem(SESSION_KEY);closeModal();dashboard();notify("AI key cleared.");return}if(a==="saveaiconfig"){const value=document.getElementById("openrouterKey")?.value?.trim();const model=document.getElementById("openrouterModel")?.value?.trim()||"openai/gpt-5-mini";if(value)sessionStorage.setItem(SESSION_KEY,value);sessionStorage.setItem(MODEL_KEY,model);closeModal();state.active?editor():dashboard();notify("AI settings saved for this browser tab.");return}if(a==="opencloud"){window.open(CLOUD_IDE_URL,"_blank","noopener,noreferrer");return}if(a==="github"){showModal("github");return}if(a==="importgithub"){importPublicGithub();return}if(a==="import"){showModal("import");return}if(a==="processimport"){importOwnProject();return}if(a==="popout"){const p=current();if(!p)return;const url=URL.createObjectURL(new Blob([sourceDoc(p)],{type:"text/html"}));window.open(url,"_blank","noopener,noreferrer");setTimeout(()=>URL.revokeObjectURL(url),60000);return}if(a==="new"){showModal("new");return}if(a==="closemodal"){closeModal();return}if(a==="create"){const name=word(document.getElementById("newName").value)||"Untitled Project";const kind=document.getElementById("newKind").value;const desc=word(document.getElementById("newDesc").value);create(name,kind,desc);return}if(a==="generate"){const prompt=word(document.getElementById("mainPrompt")?.value||state.draft);if(!prompt){notify("Describe the project you want to build.");document.getElementById("mainPrompt")?.focus();return;}generateFromPrompt(prompt);return}if(a==="settings"){showModal("settings");return}if(a==="snapshot"){snapshot();return}if(a==="history"){showModal("history");return}if(a==="export"){exportProject();return}if(a==="publish"){showModal("publish");return}if(a==="replace"){showModal("replace");return}if(a==="applyprompt"){const prompt=word(document.getElementById("replacePrompt")?.value);if(!prompt){notify("Enter your idea first.");return;}if(hasAI()){reviseWithAI(prompt);return}if(!confirm("Replace project code with a new starter? Save a snapshot first?"))return;snapshot();const p=current();p.kind=kindFor(prompt);p.description=prompt;p.files=template(p.kind,p.name,prompt);persist();closeModal();state.file="index.html";editor();notify("New starter generated.");return}if(a==="addfile"){const p=current();const filename=prompt("New file name (example: notes.json)");if(!filename)return;const clean=filename.trim();if(!/^[\w.-]+\.(html|css|js|json|md|txt)$/i.test(clean)||clean.includes("..")){notify("Use a simple file name ending in html, css, js, json, md or txt.");return}if(p.files[clean]!==undefined){notify("This file already exists.");return}p.files[clean]="";p.updated=now();persist();state.file=clean;editor();return}if(a==="refresh"){preview();return}if(a==="clearconsole"){state.logs=[];drawLogs();return}if(a==="openvercel"){window.open("https://vercel.com/new","_blank","noopener,noreferrer");return}}
document.addEventListener("click",e=>{let el=e.target.closest("[data-action],[data-nav],[data-open],[data-template],[data-duplicate],[data-delete],[data-file],[data-device],[data-restore],[data-applydesign],[data-designback]");if(!el)return;if(el.dataset.applydesign){applyDesign(el.dataset.applydesign);return}if(el.dataset.designback){state.view="editor";editor();return}if(el.dataset.action){onAction(el.dataset.action,el);return}if(el.dataset.nav){state.view=el.dataset.nav;if(el.dataset.nav!=="design")state.active=null;state.query="";dashboard();return}if(el.dataset.open){openProject(el.dataset.open);return}if(el.dataset.template){const k=kinds.find(x=>x.id===el.dataset.template);showModal("new",{kind:k.id,name:"My "+k.name,prompt:k.desc});return}if(el.dataset.file){state.file=el.dataset.file;editor();return}if(el.dataset.device){state.device=el.dataset.device;document.getElementById("previewcontainer")?.classList.toggle("mobile",state.device==="mobile");document.querySelectorAll("[data-device]").forEach(x=>x.classList.toggle("active",x.dataset.device===state.device));return}if(el.dataset.duplicate){let p=state.projects.find(x=>x.id===el.dataset.duplicate);if(!p)return;let copy=JSON.parse(JSON.stringify(p));copy.id=id();copy.name=p.name+" (copy)";copy.updated=now();copy.history=[];state.projects.unshift(copy);persist();dashboard();notify("Project duplicated.");return}if(el.dataset.delete){let p=state.projects.find(x=>x.id===el.dataset.delete);if(!p||!confirm('Delete "'+p.name+'"? Export a backup first if needed.'))return;state.projects=state.projects.filter(x=>x.id!==p.id);persist();dashboard();notify("Project deleted.");return}if(el.dataset.restore){let p=current(),snap=(p.history||[]).find(x=>x.id===el.dataset.restore);if(!snap)return;if(!confirm("Restore this snapshot?"))return;snapshot();p.files=JSON.parse(JSON.stringify(snap.files));p.updated=now();persist();closeModal();editor();notify("Snapshot restored.");}});
document.addEventListener("input",e=>{if(e.target.id==="mainPrompt")state.draft=e.target.value;if(e.target.id==="searchProjects"){state.query=e.target.value;document.getElementById("projectResults").innerHTML=projectList(state.query)}if(e.target.id==="codeEditor"){updateLines();syncEditor();}});
document.addEventListener("keyup",e=>{if(e.target.id==="codeEditor")updateCursor()});document.addEventListener("click",e=>{if(e.target.id==="codeEditor")updateCursor()});
document.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="s"){e.preventDefault();if(state.view==="editor")snapshot();else persist();}if(e.target.id==="codeEditor"&&e.key==="Tab"){e.preventDefault();const t=e.target,start=t.selectionStart,end=t.selectionEnd;t.value=t.value.slice(0,start)+"  "+t.value.slice(end);t.selectionStart=t.selectionEnd=start+2;syncEditor();updateLines();}if(e.key==="Escape"&&state.modal)closeModal();});
load();dashboard();cloudMe();
